117	func (s *Service) includedFiles(ctx context.Context, root string, patterns []string) ([]string, error) {
118		if len(patterns) == 0 {
119			return nil, nil
120		}
121		ignoredFiles, err := s.git.ListIgnoredFiles(ctx, root)
122		if err != nil {
123			return nil, err
124		}
125		return matchIncludePatterns(patterns, ignoredFiles), nil
126	}
127	
128	func matchIncludePatterns(patterns, files []string) []string {
129		ps := make([]gitignore.Pattern, 0, len(patterns))
130		for _, pattern := range patterns {
131			ps = append(ps, gitignore.ParsePattern(pattern, nil))
132		}
133		matcher := gitignore.NewMatcher(ps)
134		included := make([]string, 0, len(files))
135		for _, file := range files {
136			rel, ok := cleanRelativeFile(file)
137			if !ok || isWorktreeFile(rel) || !matcher.Match(splitRelativePath(rel), false) {
138				continue
139			}
140			included = append(included, rel)
141		}
142		return included
143	}
144	
145	func isWorktreeFile(rel string) bool {
146		slash := filepath.ToSlash(rel)
147		return slash == worktreesDir || strings.HasPrefix(slash, worktreesDir+"/")
148	}
149	
150	func cleanRelativeFile(rel string) (string, bool) {
151		if rel == "" || filepath.IsAbs(rel) {
152			return "", false
153		}
154		clean := filepath.Clean(filepath.FromSlash(rel))
155		if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
156			return "", false
157		}
158		return clean, true
159	}
160	
161	func splitRelativePath(rel string) []string {
162		return strings.Split(filepath.ToSlash(rel), "/")
163	}
164	
165	func (s *Service) copyFiles(root, dest string, files []string) {
166		for _, rel := range files {
167			if err := copyFile(filepath.Join(root, rel), filepath.Join(dest, rel)); err != nil {
168				_, _ = fmt.Fprintf(s.out, "warning: skipped %s: %v\n", rel, err)
169			}
170		}
171	}
172	
173	func copyFile(src, dst string) error {
174		srcInfo, err := os.Lstat(src)
175		if err != nil {
176			return err
177		}
178		if !srcInfo.Mode().IsRegular() {
179			return fmt.Errorf("source is not a regular file")
180		}
181		in, err := os.Open(src) //nolint:gosec // src derived from repo root + config
182		if err != nil {
183			return err
184		}
185		defer in.Close() //nolint:errcheck // read-only; close error not actionable
186		openedInfo, err := in.Stat()
187		if err != nil {
188			return err
189		}
190		if !openedInfo.Mode().IsRegular() || !os.SameFile(srcInfo, openedInfo) {
191			return fmt.Errorf("source changed while opening")
192		}
193		if err := os.MkdirAll(filepath.Dir(dst), 0o750); err != nil {
194			return err
195		}
196		out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_EXCL, srcInfo.Mode().Perm()) //nolint:gosec // dst is inside the new worktree
197		if err != nil {
198			return err
199		}
200		if _, err := io.Copy(out, in); err != nil {
201			_ = out.Close()
202			_ = os.Remove(dst)
203			return err
204		}
205		if err := out.Close(); err != nil {
206			_ = os.Remove(dst)
207			return err
208		}
209		if err := os.Chmod(dst, srcInfo.Mode().Perm()); err != nil {
210			_ = os.Remove(dst)
211			return err
212		}
213		return nil
214	}
