328	func confirmMessage(targets []Worktree) string {
329		var b strings.Builder
330		b.WriteString("Remove the following worktrees?\n")
331		for _, w := range targets {
332			_, _ = fmt.Fprintf(&b, "  - %s\n", w.Path)
333		}
334		return b.String()
335	}
