14	// LoadConfig reads .worktreeinclude from root. A missing file copies nothing.
15	func LoadConfig(root string) (Config, error) {
16		path := filepath.Join(root, configRelPath)
17		data, err := os.ReadFile(path) //nolint:gosec // path derived from repo root
18		if errors.Is(err, fs.ErrNotExist) {
19			return Config{}, nil
20		}
21		if err != nil {
22			return Config{}, fmt.Errorf("read %s: %w", path, err)
23		}
24		return Config{IncludePatterns: parseIncludePatterns(data)}, nil
25	}
26	
27	func parseIncludePatterns(data []byte) []string {
28		var patterns []string
29		for _, raw := range strings.Split(string(data), "\n") {
30			line := strings.TrimRight(raw, "\r")
31			if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
32				continue
33			}
34			patterns = append(patterns, line)
35		}
36		return patterns
37	}
