	args = append(args, opts.ExtraArgs...)
	switch {
	case opts.Shallow:
		args = append(args, "--depth=1")
	case opts.Depth > 0:
		args = append(args, fmt.Sprintf("--depth=%d", opts.Depth))
	case opts.Unshallow && isShallowRepository(ctx, opts.Dir):
		args = append(args, "--unshallow")
