272	// copyIncludedFile copies src into destRoot at rel. destRoot confines all
273	// writes to the worktree root, so a tracked symlinked directory in the
274	// branch cannot redirect the copy outside the worktree.
275	func copyIncludedFile(src string, destRoot *os.Root, rel string) error {
276		srcInfo, err := os.Lstat(src)
277		if err != nil {
278			return err //nolint:wrapcheck // lstat error is sufficient for caller context
279		}
280		if !srcInfo.Mode().IsRegular() {
281			return errors.New("source is not a regular file")
282		}
283		in, err := os.Open(src) //nolint:gosec // src derived from repo root + .worktreeinclude
284		if err != nil {
285			return err //nolint:wrapcheck // open error is sufficient for caller context
286		}
287		defer in.Close()
288		openedInfo, err := in.Stat()
289		if err != nil {
290			return err //nolint:wrapcheck // stat error is sufficient for caller context
291		}
292		if !openedInfo.Mode().IsRegular() || !os.SameFile(srcInfo, openedInfo) {
293			return errors.New("source changed while opening")
294		}
295		if err := destRoot.MkdirAll(filepath.Dir(rel), 0o750); err != nil {
296			return err //nolint:wrapcheck // mkdir error is sufficient for caller context
297		}
298		out, err := destRoot.OpenFile(rel, os.O_WRONLY|os.O_CREATE|os.O_EXCL, srcInfo.Mode().Perm())
299		if err != nil {
300			return err //nolint:wrapcheck // openfile error is sufficient for caller context
301		}
302		if _, err := io.Copy(out, in); err != nil {
303			_ = out.Close()
304			_ = destRoot.Remove(rel) //nolint:errcheck // best-effort cleanup after a failed copy
305			return err               //nolint:wrapcheck // copy error is sufficient for caller context
306		}
307		if err := out.Close(); err != nil {
308			_ = destRoot.Remove(rel) //nolint:errcheck // best-effort cleanup after a failed copy
309			return err               //nolint:wrapcheck // close error is sufficient for caller context
310		}
311		if err := destRoot.Chmod(rel, srcInfo.Mode().Perm()); err != nil {
312			_ = destRoot.Remove(rel) //nolint:errcheck // best-effort cleanup after a failed copy
313			return err               //nolint:wrapcheck // chmod error is sufficient for caller context
314		}
315		return nil
316	}
